def find_gaps(sorted_ints):
    if not sorted_ints:
        return []

    gaps = []
    prev = sorted_ints[0]

    for x in sorted_ints[1:]:
        if x == prev:
            continue
        if x > prev + 1:
            gaps.extend(range(prev + 1, x))
        prev = x

    return gaps
